    39     struct parse<JSON>
    40     {
    41        template <auto Opts, class T, is_context Ctx, class It0, class It1>
    42        GLZ_ALWAYS_INLINE static void op(T&& value, Ctx&& ctx, It0&& it, It1&& end)
    43        {
    44           if constexpr (const_value_v<T>) {
    45              if constexpr (Opts.error_on_const_read) {
    46                 ctx.error = error_code::attempt_const_read;
    47              }
    48              else {
    49                 // do not read anything into the const value
    50                 skip_value<JSON>::op<Opts>(std::forward<Ctx>(ctx), std::forward<It0>(it), std::forward<It1>(end));
    51              }
    52           }
    53           else {
    54              using V = std::remove_cvref_t<T>;
    55              from<JSON, V>::template op<Opts>(std::forward<T>(value), std::forward<Ctx>(ctx), std::forward<It0>(it),
    56                                               std::forward<It1>(end));
    57           }
    58        }
