    60        // This unknown key handler should not be given unescaped keys, that is for the user to handle.
    61        template <auto Opts, class T, is_context Ctx, class It0, class It1>
    62        static void handle_unknown(const sv& key, T&& value, Ctx&& ctx, It0&& it, It1&& end)
    63        {
    64           using ValueType = std::decay_t<decltype(value)>;
    65           if constexpr (has_unknown_reader<ValueType>) {
    66              constexpr auto& reader = meta_unknown_read_v<ValueType>;
    67              using ReaderType = meta_unknown_read_t<ValueType>;
    68              if constexpr (std::is_member_object_pointer_v<ReaderType>) {
    69                 using MemberType = typename member_value<ReaderType>::type;
    70                 if constexpr (map_subscriptable<MemberType>) {
    71                    parse<JSON>::op<Opts>((value.*reader)[key], ctx, it, end);
    72                 }
    73                 else {
    74                    static_assert(false_v<T>, "target must have subscript operator");
    75                 }
    76              }
    77              else if constexpr (std::is_member_function_pointer_v<ReaderType>) {
    78                 using ReturnType = typename return_type<ReaderType>::type;
    79                 if constexpr (std::is_void_v<ReturnType>) {
    80                    using TupleType = typename inputs_as_tuple<ReaderType>::type;
    81                    if constexpr (glz::tuple_size_v<TupleType> == 2) {
    82                       std::decay_t<glz::tuple_element_t<1, TupleType>> input{};
    83                       parse<JSON>::op<Opts>(input, ctx, it, end);
    84                       if (bool(ctx.error)) [[unlikely]]
    85                          return;
    86                       (value.*reader)(key, input);
    87                    }
    88                    else {
    89                       static_assert(false_v<T>, "method must have 2 args");
    90                    }
    91                 }
    92                 else {
    93                    static_assert(false_v<T>, "method must have void return");
    94                 }
    95              }
    96              else {
    97                 static_assert(false_v<T>, "unknown_read type not handled");
    98              }
    99           }
   100           else {
   101              skip_value<JSON>::op<Opts>(ctx, it, end);
   102           }
   103        }
   104     };
