   136     GLZ_ALWAYS_INLINE bool parse_ws_colon(is_context auto& ctx, auto&& it, auto&& end) noexcept
   137     {
   138        if (skip_ws<Opts>(ctx, it, end)) {
   139           return true;
   140        }
   141        if (match_invalid_end<':', Opts>(ctx, it, end)) {
   142           return true;
   143        }
   144        if (skip_ws<Opts>(ctx, it, end)) {
   145           return true;
   146        }
   147        return false;
