   150     template <auto Opts, class T, size_t I, class Value, class... SelectedIndex>
   151        requires(glaze_object_t<T> || reflectable<T>)
   152     void decode_index(Value&& value, is_context auto&& ctx, auto&& it, auto&& end, SelectedIndex&&... selected_index)
   153     {
   154        static constexpr auto Key = get<I>(reflect<T>::keys);
   155        static constexpr auto KeyWithEndQuote = join_v<Key, chars<"\"">>;
   156        static constexpr auto Length = KeyWithEndQuote.size();
   157
   158        if (((it + Length) < end) && comparitor<KeyWithEndQuote>(it)) [[likely]] {
   159           it += Length;
   160           if constexpr (not Opts.null_terminated) {
   161              if (it == end) [[unlikely]] {
   162                 ctx.error = error_code::unexpected_end;
   163                 return;
   164              }
   165           }
   166
   167           if (skip_ws<Opts>(ctx, it, end)) {
   168              return;
   169           }
   170           if (match_invalid_end<':', Opts>(ctx, it, end)) {
   171              return;
   172           }
   173           if (skip_ws<Opts>(ctx, it, end)) {
   174              return;
   175           }
   176
   177           using V = refl_t<T, I>;
   178
   179           if constexpr (const_value_v<V>) {
   180              if constexpr (Opts.error_on_const_read) {
   181                 ctx.error = error_code::attempt_const_read;
   182              }
   183              else {
   184                 // do not read anything into the const value
   185                 skip_value<JSON>::op<Opts>(ctx, it, end);
   186              }
   187           }
   188           else {
   189              if constexpr (glaze_object_t<T>) {
   190                 from<JSON, std::remove_cvref_t<V>>::template op<ws_handled<Opts>()>(
   191                    get_member(value, get<I>(reflect<T>::values)), ctx, it, end);
   192              }
   193              else {
   194                 from<JSON, std::remove_cvref_t<V>>::template op<ws_handled<Opts>()>(
   195                    get_member(value, get<I>(to_tie(value))), ctx, it, end);
   196              }
   197           }
   198
   199           if constexpr (Opts.error_on_missing_keys || Opts.partial_read) {
   200              ((selected_index = I), ...);
   201           }
   202        }
   203        else [[unlikely]] {
   204           if constexpr (Opts.error_on_unknown_keys) {
   205              ctx.error = error_code::unknown_key;
   206           }
   207           else {
   208              auto* start = it;
   209              skip_string_view<Opts>(ctx, it, end);
   210              if (bool(ctx.error)) [[unlikely]]
   211                 return;
   212              const sv key = {start, size_t(it - start)};
   213              ++it;
   214              if constexpr (not Opts.null_terminated) {
   215                 if (it == end) [[unlikely]] {
   216                    ctx.error = error_code::unexpected_end;
   217                    return;
   218                 }
   219              }
   220
   221              if (parse_ws_colon<Opts>(ctx, it, end)) {
   222                 return;
   223              }
   224
   225              parse<JSON>::handle_unknown<Opts>(key, value, ctx, it, end);
   226           }
   227        }
   228     }
