   230     template <auto Opts, class T, size_t I, class Value>
   231        requires(glaze_enum_t<T> || (meta_keys<T> && std::is_enum_v<T>))
   232     void decode_index(Value&& value, is_context auto&& ctx, auto&& it, auto&& end) noexcept
   233     {
   234        static constexpr auto TargetKey = glz::get<I>(reflect<T>::keys);
   235        static constexpr auto Length = TargetKey.size();
   236
   237        if (((it + Length) < end) && comparitor<TargetKey>(it)) [[likely]] {
   238           it += Length;
   239           if (*it != '"') [[unlikely]] {
   240              ctx.error = error_code::unexpected_enum;
   241              return;
   242           }
   243           value = get<I>(reflect<T>::values);
   244
   245           ++it;
   246           if constexpr (not Opts.null_terminated) {
   247              if (it == end) {
   248                 ctx.error = error_code::end_reached;
   249                 return;
   250              }
   251           }
   252        }
   253        else [[unlikely]] {
   254           ctx.error = error_code::unexpected_enum;
   255           return;
